"""
ERPNext Server Script for BOM Item Spec
=======================================

Document Type: BOM Item Spec
Event: After Save

This script handles:
1. Bidirectional linking between BOM Item and BOM Item Spec
2. Auto-updating BOM Item descriptions with formatted spec data
3. Auto-updating main BOM descriptions with aggregated component data

Business Context:
- Jewelry manufacturing with detailed component specifications
- Multi-level description updates (Item → BOM Item → BOM)
- Formatted output with proper units and professional presentation

"""

try:
    # Step 1: Create bidirectional linking
    if doc.bom_item_id and frappe.db.exists("BOM Item", doc.bom_item_id):
        try:
            frappe.db.set_value("BOM Item", doc.bom_item_id, "bom_item_spec", doc.name)
            print(f"Linked BOM Item Spec {doc.name} to BOM Item {doc.bom_item_id}")
        except Exception as e:
            frappe.log_error(f"Failed to link BOM Item Spec {doc.name} to BOM Item {doc.bom_item_id}: {str(e)}")

    # Step 2: Update individual BOM Item description
    if doc.bom_item_id and frappe.db.exists("BOM Item", doc.bom_item_id):
        try:
            # Get BOM Item for basic info
            bom_item = frappe.get_doc('BOM Item', doc.bom_item_id)
            
            # Build description parts
            parts = []
            
            # Basic item information
            if bom_item.item_name:
                parts.append(f"Item: {bom_item.item_name}")
            if bom_item.item_group:
                parts.append(f"Group: {bom_item.item_group}")
            
            # Gemstone specifications
            if doc.gemstone:
                parts.append(f"Gemstone: {doc.gemstone}")
            if doc.stone_treatments:
                parts.append(f"Treatments: {doc.stone_treatments}")
            if doc.grade:
                parts.append(f"Grade: {doc.grade}")
            if doc.cut:
                parts.append(f"Cut: {doc.cut}")
            if doc.setting_type:
                parts.append(f"Setting: {doc.setting_type}")
            if doc.merch_color_attribute:
                parts.append(f"Color: {doc.merch_color_attribute}")
            if doc.country_of_origin:
                parts.append(f"Origin: {doc.country_of_origin}")
            
            # Measurements and quantities with inline formatting
            if doc.stone_pieces and doc.stone_pieces > 0:
                parts.append(f"Pieces: {int(doc.stone_pieces)} pcs")
                
            if doc.sku_carat_weight and doc.sku_carat_weight > 0:
                formatted_sku = f"{float(doc.sku_carat_weight):.3f}".rstrip('0').rstrip('.')
                parts.append(f"SKU Weight: {formatted_sku}ct")
                
            if doc.avg_carat_weight and doc.avg_carat_weight > 0:
                formatted_avg = f"{float(doc.avg_carat_weight):.3f}".rstrip('0').rstrip('.')
                parts.append(f"Avg Carat: {formatted_avg}ct")
            
            # Metal specifications
            if doc.metal_group:
                parts.append(f"Metal: {doc.metal_group}")
                
            if doc.sku_metal_weight and doc.sku_metal_weight > 0:
                formatted_sku_metal = f"{float(doc.sku_metal_weight):.3f}".rstrip('0').rstrip('.')
                parts.append(f"SKU Metal: {formatted_sku_metal}g")
                
            if doc.avg_metal_weight and doc.avg_metal_weight > 0:
                formatted_avg_metal = f"{float(doc.avg_metal_weight):.3f}".rstrip('0').rstrip('.')
                parts.append(f"Avg Metal: {formatted_avg_metal}g")
            
            # Findings and chains
            if doc.finding_pieces and doc.finding_pieces > 0:
                parts.append(f"Findings: {int(doc.finding_pieces)} pcs")
                
            if doc.length and doc.length > 0:
                formatted_length = f"{float(doc.length):.1f}".rstrip('0').rstrip('.')
                unit = doc.length_uom if doc.length_uom else 'mm'
                parts.append(f"Length: {formatted_length}{unit}")
                
            if doc.weight_per_piece and doc.weight_per_piece > 0:
                formatted_weight_piece = f"{float(doc.weight_per_piece):.3f}".rstrip('0').rstrip('.')
                parts.append(f"Weight/Piece: {formatted_weight_piece}g")
                
            if doc.total_weight and doc.total_weight > 0:
                formatted_total_weight = f"{float(doc.total_weight):.3f}".rstrip('0').rstrip('.')
                parts.append(f"Total Weight: {formatted_total_weight}g")
            
            # Update BOM Item description
            new_description = " | ".join(parts)
            frappe.db.set_value('BOM Item', doc.bom_item_id, 'description', new_description)
            print(f"Updated BOM Item {doc.bom_item_id} description")
            
        except Exception as e:
            frappe.log_error(f"Failed to update BOM Item description for {doc.bom_item_id}: {str(e)}")

    # Step 3: Update main BOM description with aggregated data
    if doc.bom and frappe.db.exists("BOM", doc.bom):
        try:
            # Get all BOM Item Specs for this BOM
            all_specs = frappe.db.get_all('BOM Item Spec',
                filters={'bom': doc.bom},
                fields=[
                    'name', 'item', 'item_group', 'gemstone', 'stone_treatments', 'merch_color_attribute',
                    'country_of_origin', 'cut', 'stone_pieces', 'setting_type', 'grade', 'avg_carat_weight',
                    'sku_carat_weight', 'metal_group', 'sku_metal_weight', 'avg_metal_weight', 
                    'finding_pieces', 'length', 'weight_per_piece', 'length_uom', 'total_weight'
                ]
            )
            
            # Get main BOM document
            bom_doc = frappe.get_doc('BOM', doc.bom)
            
            # Build main BOM description
            parts = []
            
            # Main BOM information
            if bom_doc.item_name:
                parts.append(f"<b>{bom_doc.item_name}</b>")
            if bom_doc.item_group:
                parts.append(f"Type: {bom_doc.item_group}")
            
            # Categorize specs by component type
            stone_specs = []
            metal_specs = []
            finding_specs = []
            other_specs = []
            
            for spec in all_specs:
                if spec.gemstone or spec.stone_pieces or spec.avg_carat_weight:
                    stone_specs.append(spec)
                elif spec.metal_group or spec.sku_metal_weight or spec.avg_metal_weight:
                    metal_specs.append(spec)
                elif spec.finding_pieces or spec.length or spec.weight_per_piece:
                    finding_specs.append(spec)
                else:
                    other_specs.append(spec)
            
            # Build stone specifications inline
            if stone_specs:
                stone_descriptions = []
                for spec in stone_specs:
                    stone_parts = []
                    
                    # Core stone info
                    if spec.gemstone:
                        stone_parts.append(spec.gemstone)
                    if spec.cut:
                        stone_parts.append(spec.cut)
                    if spec.merch_color_attribute:
                        stone_parts.append(spec.merch_color_attribute)
                    if spec.grade:
                        stone_parts.append(f"Grade {spec.grade}")
                    
                    # Quantities and weights
                    if spec.stone_pieces and spec.stone_pieces > 0:
                        stone_parts.append(f"{int(spec.stone_pieces)} pcs")
                        
                    if spec.avg_carat_weight and spec.avg_carat_weight > 0:
                        formatted_carat = f"{float(spec.avg_carat_weight):.3f}".rstrip('0').rstrip('.')
                        stone_parts.append(f"{formatted_carat}ct")
                    
                    # Origin and treatments (in parentheses)
                    if spec.country_of_origin:
                        stone_parts.append(f"({spec.country_of_origin})")
                    if spec.stone_treatments:
                        stone_parts.append(f"({spec.stone_treatments})")
                    
                    if stone_parts:
                        stone_descriptions.append(' '.join(stone_parts))
                
                if stone_descriptions:
                    parts.append(f"Stones: {', '.join(stone_descriptions)}")
            
            # Build metal specifications inline
            if metal_specs:
                metal_descriptions = []
                for spec in metal_specs:
                    metal_parts = []
                    
                    # Metal type
                    if spec.metal_group:
                        metal_parts.append(spec.metal_group)
                    
                    # Weight (prefer avg over sku)
                    if spec.avg_metal_weight and spec.avg_metal_weight > 0:
                        formatted_weight = f"{float(spec.avg_metal_weight):.3f}".rstrip('0').rstrip('.')
                        metal_parts.append(f"{formatted_weight}g")
                    elif spec.sku_metal_weight and spec.sku_metal_weight > 0:
                        formatted_weight = f"{float(spec.sku_metal_weight):.3f}".rstrip('0').rstrip('.')
                        metal_parts.append(f"{formatted_weight}g")
                    
                    if metal_parts:
                        metal_descriptions.append(' '.join(metal_parts))
                
                if metal_descriptions:
                    parts.append(f"Metal: {', '.join(metal_descriptions)}")
            
            # Build finding/chain specifications inline
            if finding_specs:
                finding_descriptions = []
                for spec in finding_specs:
                    finding_parts = []
                    
                    # Finding pieces
                    if spec.finding_pieces and spec.finding_pieces > 0:
                        finding_parts.append(f"{int(spec.finding_pieces)} findings")
                    
                    # Length
                    if spec.length and spec.length > 0:
                        formatted_length = f"{float(spec.length):.1f}".rstrip('0').rstrip('.')
                        unit = spec.length_uom if spec.length_uom else 'mm'
                        finding_parts.append(f"{formatted_length}{unit}")
                    
                    # Weights
                    if spec.weight_per_piece and spec.weight_per_piece > 0:
                        formatted_weight_piece = f"{float(spec.weight_per_piece):.3f}".rstrip('0').rstrip('.')
                        finding_parts.append(f"{formatted_weight_piece}g/pc")
                        
                    if spec.total_weight and spec.total_weight > 0:
                        formatted_total = f"{float(spec.total_weight):.3f}".rstrip('0').rstrip('.')
                        finding_parts.append(f"{formatted_total}g total")
                    
                    if finding_parts:
                        finding_descriptions.append(' '.join(finding_parts))
                
                if finding_descriptions:
                    parts.append(f"Findings: {', '.join(finding_descriptions)}")
            
            # Other components
            if other_specs:
                other_descriptions = [spec.item for spec in other_specs if spec.item]
                if other_descriptions:
                    parts.append(f"Components: {', '.join(other_descriptions)}")
            
            # Update main BOM description
            new_description = " | ".join(parts)
            frappe.db.set_value('BOM', doc.bom, 'description', new_description)
            print(f"Updated main BOM {doc.bom} description")
            
        except Exception as e:
            frappe.log_error(f"Failed to update main BOM description for {doc.bom}: {str(e)}")
    
    print(f"BOM Item Spec {doc.name} processing completed successfully")
    
except Exception as e:
    frappe.log_error(f"BOM Item Spec {doc.name} processing failed: {str(e)}")
    # Don't throw error to prevent save failure, but log for debugging

item_rows = frappe.get_all(
    "Sales Order Item",
    filters={"parent": frappe.form_dict.get("sales_order")},
    fields=["name"]
)
if item_rows:
    for row in item_rows:
        frappe.db.set_value("Sales Order Item", row.name, "delivery_date", frappe.form_dict.get("delivery_date"))
frappe.response["message"] = "Delivery date updated successfully."

def get_si_items(sales_invoices):
    if isinstance(sales_invoices, str):
        sales_invoices = json.loads(sales_invoices)

    items = []
    for si in sales_invoices:
        doc = frappe.get_doc("Sales Invoice", si)
        for item in doc.items:
            items.append({
                "parent": si,
                "item_code": item.item_code,
                "item_name": item.item_name,
                "qty": item.qty,
                "uom": item.uom,
                "rate": item.rate,
                "amount": item.amount
            })
    return items

def get_sales_order_items_with_po(so_list_json):
    try:
        so_list = json.loads(so_list_json)

        if not so_list:
            return []

        items = []
        for so_name in so_list:
            so_doc = frappe.get_doc("Sales Order", so_name)
            for row in so_doc.items:
                items.append({
                    "item_code": row.item_code,
                    "item_name": row.item_name,
                    "qty": row.qty,
                    "rate": row.rate,
                    "amount": row.amount
                })

        return items

    except Exception as e:
        frappe.log_error(frappe.get_traceback(), "Error in get_sales_order_items_with_po")
        return []

bom_name = doc.name

worksheets = frappe.get_all(
    "Customer Worksheet",
    filters={},
    fields=["name"]
)

for ws in worksheets:
    ws_doc = frappe.get_doc("Customer Worksheet", ws.name)
    updated = False

    for item in ws_doc.customer_worksheet_items:
        if item.default_bom == bom_name:
            item.default_bom = ""
            updated = True

    if updated:
        ws_doc.save(ignore_permissions=True)

if doc.custom_bom_items:
    updated_boms = []

    for row in doc.custom_bom_items:
        if row.bom_no and row.item_code:
            bom_items = frappe.get_all(
                "BOM Item",
                filters={
                    "parent": row.bom_no,
                    "item_code": ["like", row.item_code.strip()],
                },
                fields=["name", "rate", "amount"]
            )

            for bom_item in bom_items:
                if bom_item.rate != row.rate or bom_item.amount != row.amount:
                    frappe.db.set_value("BOM Item", bom_item.name, {
                        "rate": row.rate,
                        "amount": row.amount
                    })
                    updated_boms.append(row.bom_no)

    if updated_boms:
        frappe.msgprint("BOMs updated.")
    else:
        frappe.msgprint("No BOM update required.")

# ERPNext Server Script: BOM Change Detection (Fixed)
# DocType: Sales Order
# Event: validate
# Description: Detects BOM changes and sets flags for client handling

def detect_and_handle_bom_changes():
    """Detect BOM changes and set flags for client handling"""
    
    # Skip if no BOM linked
    if not doc.get("custom_item_bom"):
        return
    
    # Skip if no BOM items to compare
    current_bom_items = doc.get("custom_bom_items") or []
    if not current_bom_items:
        return
    
    try:
        # Get the linked BOM for comparison
        bom_name = doc.get("custom_item_bom")
        
        if not frappe.db.exists("BOM", bom_name):
            # Don't show error message during save, just log it
            frappe.log_error(f"Linked BOM {bom_name} not found for SO {doc.name}")
            return
        
        # Get BOM status first
        bom_status = frappe.db.get_value("BOM", bom_name, "docstatus")
        
        # Compare current SO BOM items with actual BOM items
        changes_detected = compare_so_bom_with_original(current_bom_items, bom_name)
        
        if changes_detected:
            # Set flags for client script to handle
            doc.custom_bom_changes_detected = 1
            doc.custom_bom_status = bom_status
            doc.custom_bom_changes_details = changes_detected
            
            # Log the detection
            frappe.logger().info(f"BOM changes detected for SO {doc.name}: {changes_detected}")
        else:
            # Clear flags if no changes
            doc.custom_bom_changes_detected = 0
            doc.custom_bom_changes_details = ""
            
    except Exception as e:
        frappe.log_error(f"BOM change detection error for SO {doc.name}: {str(e)}")
        # Don't block save due to BOM comparison errors
        pass

def compare_so_bom_with_original(so_bom_items, bom_name):
    """Compare Sales Order BOM items with original BOM"""
    
    try:
        # Get original BOM items
        original_bom = frappe.get_doc("BOM", bom_name)
        original_items = original_bom.items or []
        
        # Create comparison dictionaries
        so_items_dict = {}
        for item in so_bom_items:
            key = item.get("item_code")
            if key:
                # Try multiple rate fields
                rate = 0
                if item.get("rate"):
                    rate = float(item.get("rate", 0))
                elif item.get("custom_selling_rate"):
                    rate = float(item.get("custom_selling_rate", 0))
                elif item.get("buying_rate"):
                    rate = float(item.get("buying_rate", 0))
                
                so_items_dict[key] = {
                    "qty": float(item.get("qty", 0)),
                    "rate": rate,
                    "uom": item.get("uom", ""),
                    "description": item.get("description", "")
                }
        
        original_items_dict = {}
        for item in original_items:
            key = item.get("item_code")
            if key:
                original_items_dict[key] = {
                    "qty": float(item.get("qty", 0)),
                    "rate": float(item.get("rate", 0)),
                    "uom": item.get("uom", ""),
                    "description": item.get("description", "")
                }
        
        # Track changes
        changes = []
        
        # Check for new items
        for item_code in so_items_dict:
            if item_code not in original_items_dict:
                changes.append(f"Added: {item_code}")
        
        # Check for removed items
        for item_code in original_items_dict:
            if item_code not in so_items_dict:
                changes.append(f"Removed: {item_code}")
        
        # Check for modified items
        for item_code in so_items_dict:
            if item_code in original_items_dict:
                so_item = so_items_dict[item_code]
                orig_item = original_items_dict[item_code]
                
                if so_item["qty"] != orig_item["qty"]:
                    changes.append(f"Qty changed for {item_code}: {orig_item['qty']} → {so_item['qty']}")
                
                if so_item["rate"] != orig_item["rate"]:
                    changes.append(f"Rate changed for {item_code}: {orig_item['rate']} → {so_item['rate']}")
                
                if so_item["uom"] != orig_item["uom"]:
                    changes.append(f"UOM changed for {item_code}: {orig_item['uom']} → {so_item['uom']}")
        
        # Return changes summary or False if no changes
        if changes:
            return " | ".join(changes[:3])  # Limit to first 3 changes for display
        else:
            return False
            
    except Exception as e:
        frappe.log_error(f"BOM comparison error: {str(e)}")
        return False

# Execute the main function
detect_and_handle_bom_changes()

mr_name = doc.name  # The Material Request to unlink

sales_orders = frappe.get_all(
    "Sales Order",
    filters={},
    fields=["name"]
)

for so in sales_orders:
    so_doc = frappe.get_doc("Sales Order", so.name)
    updated = False

    # Unlink from custom_bom_items child table
    for bom_item in so_doc.get("custom_bom_items") or []:
        if str(bom_item.custom_material_request_id) == mr_name:
            bom_item.custom_material_request_id = ""
            updated = True

    if updated:
        so_doc.save(ignore_permissions=True)

if doc.custom_sales_order_type == "Stone" and doc.custom_sales_order_id:
    linked_so = frappe.get_doc("Sales Order", doc.custom_sales_order_id)
    if linked_so.docstatus != 1:
        frappe.throw(
            f'Cannot submit this Sales Order because the linked Sales Order <b style="color:blue">{linked_so.name}</b> is not submitted yet.'
        )
